    // heart and the moment you're in
    const plateWidth = Math.min(width, Math.max(30, columns * scale + 6))
    const nameplate = (
      <Box justifyContent="center">
        <Box flexDirection="column" width={plateWidth}>
          <Box justifyContent="space-between">
