      : choosing.isOpen && choosing.mode === 'sessions' ? sessionList
      : choosing.isOpen && choosing.mode === 'journal' ? journalView
      : choosing.isOpen && choosing.mode === 'wardrobe' ? wardrobe
      : choosing.isOpen ? (
