// The world outside the terminal: the time of day, the season, the day of the
// week, and the weather where you are

export type PartOfDay = 'dawn' | 'morning' | 'afternoon' | 'evening' | 'night' | 'lateNight'
export type Season = 'spring' | 'summer' | 'autumn' | 'winter'
export type DayKind = 'weekday' | 'friday' | 'weekend'
export type Sky = 'clear' | 'cloudy' | 'fog' | 'drizzle' | 'rain' | 'snow' | 'storm'

export type Weather = {
  sky: Sky
  /** Degrees in the local unit */
  temperature: number
  unit: 'C' | 'F'
  /** Where it's from, in words: "Tokyo" */
  place: string
  isDay: boolean
  /** You named the place yourself, so it can be shown; a guess from your IP stays hidden */
  isChosen?: boolean
  /** Wind speed in km/h */
  wind?: number
}

// Windy enough for gusts to blow past
export const isWindy = (w: Weather) => (w.wind ?? 0) >= 30

/** Where to ask about the weather for, and how it was found */
export type Place = { latitude: number; longitude: number; name: string; country: string }

export type WeatherSetting = { mode: 'auto' | 'city' | 'off'; city?: string }

export function partOfDay(hour: number): PartOfDay {
  if (hour < 5) return 'lateNight'
  if (hour < 8) return 'dawn'
  if (hour < 12) return 'morning'
  if (hour < 17) return 'afternoon'
  if (hour < 21) return 'evening'
  return 'night'
}

// Meteorological seasons, flipped south of the equator
export function seasonOf(month: number, latitude = 45): Season {
  const north: Season[] = ['winter', 'winter', 'spring', 'spring', 'spring', 'summer', 'summer', 'summer', 'autumn', 'autumn', 'autumn', 'winter']
  const season = north[month] ?? 'spring'
  if (latitude >= 0) return season
  return ({ winter: 'summer', summer: 'winter', spring: 'autumn', autumn: 'spring' } as const)[season]
}

export function dayKind(weekday: number): DayKind {
  if (weekday === 0 || weekday === 6) return 'weekend'
  return weekday === 5 ? 'friday' : 'weekday'
}

// WMO weather codes, as Open-Meteo reports them
export function skyOf(code: number): Sky {
  if (code <= 1) return 'clear'
  if (code <= 3) return 'cloudy'
  if (code === 45 || code === 48) return 'fog'
  if (code >= 51 && code <= 57) return 'drizzle'
  if ((code >= 61 && code <= 67) || (code >= 80 && code <= 82)) return 'rain'
  if ((code >= 71 && code <= 77) || code === 85 || code === 86) return 'snow'
  if (code >= 95) return 'storm'
  return 'cloudy'
}

// Fahrenheit where people use it
export const unitFor = (country: string): 'C' | 'F' => (['US', 'LR', 'MM', 'BS', 'KY', 'PW', 'FM', 'MH'].includes(country.toUpperCase()) ? 'F' : 'C')

export function glyph(w: Weather): string {
  switch (w.sky) {
    case 'clear':
      return w.isDay ? '☀' : '☾'
    case 'cloudy':
      return '☁'
    case 'fog':
      return '≈'
    case 'drizzle':
    case 'rain':
      return '☂'
    case 'snow':
      return '❄'
    case 'storm':
      return '⚡'
  }
}

/** One line about the world, for the pane: "☂ 12°C Tokyo · evening". The
 * season isn't named: it's shown, on them and in the air. The place only when
 * you chose it: a guess from your IP isn't always right */
export function describeWorld(w: Weather | undefined, part: PartOfDay): string {
  const when = part === 'lateNight' ? 'late night' : part
  if (w === undefined) return when
  const windy = isWindy(w) ? ' ≋' : ''
  return `${glyph(w)}${windy} ${Math.round(w.temperature)}°${w.unit}${w.isChosen ? ` ${w.place}` : ''} · ${when}`
}

/** " in Tokyo" for a place you chose, nothing for a guess */
export const where = (w: Weather) => (w.isChosen ? ` in ${w.place}` : '')

// The answers the weather and location services give, read defensively

export function readForecast(text: string, place: Place): Weather | undefined {
  try {
    const body = JSON.parse(text) as { current?: { temperature_2m?: number; weather_code?: number; is_day?: number; wind_speed_10m?: number } }
    const c = body.current
    if (typeof c?.temperature_2m !== 'number' || typeof c.weather_code !== 'number') return undefined
    const unit = unitFor(place.country)
    const temperature = unit === 'F' ? c.temperature_2m * 1.8 + 32 : c.temperature_2m
    return { sky: skyOf(c.weather_code), temperature, unit, place: place.name, isDay: c.is_day !== 0, wind: c.wind_speed_10m }
  } catch {
    return undefined
  }
}

export function readGeocode(text: string): Place | undefined {
  try {
    const first = (JSON.parse(text) as { results?: { latitude: number; longitude: number; name: string; country_code?: string }[] }).results?.[0]
    if (!first || typeof first.latitude !== 'number') return undefined
    return { latitude: first.latitude, longitude: first.longitude, name: first.name, country: first.country_code ?? '' }
  } catch {
    return undefined
  }
}

export function readIpLookup(text: string): Place | undefined {
  try {
    const body = JSON.parse(text) as { success?: boolean; latitude?: number; longitude?: number; city?: string; country_code?: string }
    if (body.success === false || typeof body.latitude !== 'number' || typeof body.longitude !== 'number') return undefined
    return { latitude: body.latitude, longitude: body.longitude, name: body.city ?? 'here', country: body.country_code ?? '' }
  } catch {
    return undefined
  }
}

export const forecastUrl = (p: Place) =>
  `https://api.open-meteo.com/v1/forecast?latitude=${p.latitude.toFixed(1)}&longitude=${p.longitude.toFixed(1)}&current=temperature_2m,weather_code,is_day,wind_speed_10m`
export const geocodeUrl = (city: string) => `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1`
export const IP_LOOKUP_URL = 'https://ipwho.is/'

files.hooks/routine.ts:
// Their own little routine: a tea break after a long stretch of work, a coffee
// in the morning, and a bite to eat around mealtimes. Neither ever holds up Claude: work calls their back.

export const TICK_MS = 250
const ticks = (minutes: number) => (minutes * 60 * 1000) / TICK_MS

// Work this long without a pause and they take a break when things go quiet
export const BREAK_AFTER = ticks(45)
export const BREAK_FOR = ticks(5)
export const SNACK_FOR = ticks(3)

const MEALS: [number, number, string][] = [
  [8, 9, 'breakfast'],
  [12, 13, 'lunch'],
  [18, 19, 'dinner'],
]

// The meal it's time for, keyed by day so they have each one once
export function mealtime(now: number): { key: string; name: string } | undefined {
  const at = new Date(now)
  const hour = at.getHours()
  const meal = MEALS.find(([from, to]) => hour >= from && hour < to)
  if (!meal) return undefined
  const day = `${at.getFullYear()}-${at.getMonth() + 1}-${at.getDate()}`
  return { key: `${day}:${meal[2]}`, name: meal[2] }
}

// One coffee break a morning, at a time of its own each day between half past
// nine and noon, so it isn't always on the dot. Keyed by day so it's once
export const COFFEE_FOR = ticks(2)
const COFFEE_FROM = 9 * 60 + 30
const COFFEE_UNTIL = 12 * 60

export function coffeeTime(now: number): string | undefined {
  const at = new Date(now)
  const day = `${at.getFullYear()}-${at.getMonth() + 1}-${at.getDate()}`
  let seed = 0
  for (const ch of day) seed = (seed * 31 + ch.charCodeAt(0)) % 9973
  const start = COFFEE_FROM + (seed % (COFFEE_UNTIL - COFFEE_FROM - 30))
  const minute = at.getHours() * 60 + at.getMinutes()
  return minute >= start && minute < COFFEE_UNTIL ? `${day}:coffee` : undefined
}

// Every hour and a half or so, while you're around, they sip some water and
// gently remind you to have some. Nothing to answer, nothing counted
export const WATER_EVERY = ticks(90)
export const WATER_FOR = ticks(2)
// You count as around if you typed or sent something this recently
export const AROUND = ticks(10)

// An hour without you typing or sending anything, and they say they miss you:
// once for each time you're away, however long
export const MISS_AFTER = ticks(60)
export const MISS_FOR = ticks(10)

// A line to use next: any but the last one, varied by the moment
export function nextLine(count: number, last: number, frame: number): number {
  if (count <= 1) return 0
  const step = 1 + (frame % (count - 1))
  return ((last < 0 ? 0 : last) + step) % count
}

files.characters/index.ts:
// Every character there is. To add one, write a file like ./aichan.ts and list it here.

import { aichan } from './aichan'
import { kai } from './kai'
import { sora } from './sora'
import type { Character, Line, Lines, Standing, Version, WeatherVerb } from './types'
import type { Season } from '../hooks/world'

export const CHARACTERS: readonly Character[] = [aichan, kai, sora]
export const DEFAULT = aichan

export const byId = (id: unknown): Character | undefined => CHARACTERS.find(c => c.id === id)

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

// A birthday as people say it: "3 April"
export const birthdayOf = (c: Character) => `${c.birthday.day} ${MONTHS[c.birthday.month - 1] ?? ''}`

// How a character reads in a list: "cheerful · woman · she/her · birthday 3 April"
export const describeCharacter = (c: Character) => `${c.temperament} · ${c.gender} · ${c.pronouns.they}/${c.pronouns.them} · birthday ${birthdayOf(c)}`

// The characters a search finds. Every word typed must match: names, ids and
// genders as you type them ("ka" finds Kai), pronouns only whole ("he" finds
// he/him, not she/her)
export function search(query: string, from: readonly Character[] = CHARACTERS): Character[] {
  const words = query.toLowerCase().split(/[\s/]+/).filter(Boolean)
  return from.filter(c => {
    const named = [c.id, c.name, c.gender].map(x => x.toLowerCase())
    const pronouns = Object.values(c.pronouns).map(x => x.toLowerCase())
    return words.every(word => named.some(x => x.startsWith(word)) || pronouns.includes(word))
  })
}

export type LineKey = keyof Lines
export type Say = (key: LineKey, vars?: Record<string, string | number>) => string

/** A newcomer: no hearts, nothing earned */
export const STRANGER: Standing = { hearts: 0, unlocked: [] }

export const textOf = (v: Version) => (typeof v === 'string' ? v : v.text)

// Whether a version is open to you: any time, once you're close enough, or once earned
export const isOpen = (v: Version, s: Standing) =>
  typeof v === 'string' || ((v.hearts ?? 0) <= s.hearts && (v.unlock === undefined || s.unlocked.includes(v.unlock)))

/** Every version of a line, each with its place in the list: the last part of its id */
export const versionsOf = (raw: Line): readonly Version[] => (Array.isArray(raw) ? raw : [raw as Version])

// The versions open to you, keeping their places
export function openOf(raw: Line, s: Standing): { text: string; index: number }[] {
  return versionsOf(raw).flatMap((v, index) => (isOpen(v, s) ? [{ text: textOf(v), index }] : []))
}

// One of the open versions, picked by a number that moves on: a turn, a frame
export function pickOpen(raw: Line, s: Standing, seed: number): { text: string; index: number } | undefined {
  const open = openOf(raw, s)
  return open.length === 0 ? undefined : open[seed % open.length]
}

// A character's line, with {name}, their pronouns and the line's own values
// filled in. A line with versions takes the open ones in turn, starting with
// the first. Each line said is reported by its id: "kai.failing.2"
export function voiceOf(c: Character, standing: () => Standing = () => STRANGER, heard?: (id: string) => void): Say {
  const turns = new Map<LineKey, number>()
  return (key, vars = {}) => {
    const turn = turns.get(key) ?? 0
    turns.set(key, turn + 1)
    const picked = pickOpen(c.voice.lines[key], standing(), turn)
    if (picked === undefined) return ''
    heard?.(`${c.id}.${key}.${picked.index}`)
    const fill: Record<string, string | number> = { name: c.name, ...c.pronouns, ...vars }
    return picked.text.replace(/\{(\w+)\}/g, (all, name: string) => String(fill[name] ?? all))
  }
}


// The words for Claude's spinner: their own, the season's (unless seasons are
// off), the day's weather, and every one unlocked by an achievement
export function spinnerWords(
  c: Character,
  season: Season | undefined,
  weather: readonly WeatherVerb[],
  unlocked: readonly string[],
): string[] {
  const seasonal = season ? c.voice.verbs.seasons[season] : []
  const today = weather.flatMap(kind => c.voice.verbs.weather[kind] ?? [])
  const earned = unlocked.flatMap(id => c.voice.verbs.achievements[id] ?? [])
  return [...c.voice.spinner, ...seasonal, ...today, ...earned]
}

export type { Character } from './types'

