import type { Accessory, Air, ArmKind } from '../hooks/sprite'

export type Prop = {
  name: string
  /** Where its top-left pixel goes on the 32 × 44 portrait */
  at: { x: number; y: number }
  /** Frames of pixels, shown in turn: '1' to '9' are its own colors, ':' leaves what's there */
  frames: string[][]
